      if(c.状态[k]!==undefined)h+='<span class="pill"><b>'+k+'</b> '+esc(c.状态[k])+'</span>';
    });
    if(c.魔力)h+='<span class="pill"><b>魔力</b> '+esc(c.魔力.类型||'无')+(c.魔力.转化&&c.魔力.转化!=='无'?' → '+esc(c.魔力.转化):'')+'</span>';
    if(c.状态.异常&&Object.keys(c.状态.异常).length){
      h+='<div class="chips" style="width:100%;margin-top:5px">';
      Object.keys(c.状态.异常).forEach(function(k){
        var e=c.状态.异常[k];h+='<span class="chip">'+esc(k)+'：'+esc((e&&e.效果)||'')+'</span>';
      });
      h+='</div>';
    }
    h+='</div></div>';
  }
  // 堕落追踪
  h+='<div class="sec"><h4>堕落追踪</h4>';
  TRACKS.forEach(function(t){
    h+='<div class="track"><span class="lbl">'+t[1]+'</span><div class="bar"><i style="width:'+pct(c[t[0]])+';background:'+barC(c[t[0]])+'"></i></div><span class="val">'+num(c[t[0]])+'</span></div>';
  });
  if(has(c.魔化形态))h+='<div class="kv" style="margin-top:7px"><span class="k">魔化形态</span><span class="v">'+esc(c.魔化形态)+'</span></div>';
  if(c.堕落六维){var LIU=['道德沦丧','共情泯灭','欲望沉溺','自我消解','手段残酷','罪责开脱'];
    LIU.forEach(function(k){var v=num((c.堕落六维||{})[k]);h+='<div class="track"><span class="lbl">'+k+'</span><div class="bar"><i style="width:'+pct(v)+';background:'+barC(v)+'"></i></div><span class="val">'+v+'</span></div>';});
    h+='</div>';}
  if(has(c.魔化表现))h+='<div class="kv" style="margin-top:7px"><span class="k">魔化表现</span><span class="v">'+esc(c.魔化表现)+'</span></div>';
  if(has(c.淫化表现))h+='<div class="kv" style="margin-top:7px"><span class="k">淫化表现</span><span class="v">'+esc(c.淫化表现)+'</span></div>';
  h+=pre(c.当前认知);
  h+='</div>';
  // 心里话/背景
  if(has(c.心里话))h+='<div class="sec"><h4>心里话</h4>'+pre(c.心里话)+'</div>';
  if(has(c.背景故事))h+='<div class="sec"><h4>背景</h4>'+pre(c.背景故事)+'</div>';
  // 关系
  if(c.好感度!==undefined||(c.关系标签||[]).length){
    h+='<div class="sec"><h4>关系</h4><div class="kv">';
    if(c.好感度!==undefined)h+='<span class="k">好感度</span><span class="v"><b style="color:'+(num(c.好感度)<0?'#e0707a':num(c.好感度)>=60?'#e8c87a':'#4fd68a')+'">'+num(c.好感度)+'</b></span>';
    if((c.关系标签||[]).length)h+='<span class="k">标签</span><span class="v">'+esc(fmtList(c.关系标签))+'</span>';
    h+='</div></div>';
  }
  h+='</div></div>';

  document.getElementById('app').innerHTML=h;
})();
</script>
