    let lastHandledMessageId = null;
    let registeredListeners = [];

    function log(...args) {
        if (CONFIG.debug) console.log(`[${SCRIPT_NAME}]`, ...args);
    }

    function warn(...args) {
        if (CONFIG.debug) console.warn(`[${SCRIPT_NAME}]`, ...args);
    }

    function toast(message, type = 'info') {
        try {
            const win = getSTWindow();
            const t = win?.toastr || window.toastr;
            if (t && t[type]) t[type](message, SCRIPT_NAME);
        } catch {}
    }

    function escapeHtml(value) {
        return String(value ?? '')
            .replaceAll('&', '&amp;')
            .replaceAll('<', '&lt;')
            .replaceAll('>', '&gt;')
            .replaceAll('"', '&quot;')
            .replaceAll("'", '&#039;');
    }

    function escapeJsonStringContent(value) {
        return JSON.stringify(String(value ?? '')).slice(1, -1);
    }

    function hasQueryParam(url, name) {
        try {
            const parsed = new URL(url, location.href);
            return parsed.searchParams.has(name);
        } catch {
            return new RegExp(`[?&]${name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}=`, 'i').test(url);
        }
    }

    function appendQueryParam(url, name, value) {
        if (!name || value == null || value === '') return url;
        const sep = url.includes('?') ? '&' : '?';
        return `${url}${sep}${encodeURIComponent(name)}=${encodeURIComponent(value)}`;
    }

    function clampNumber(value, min, max, fallback) {
        const n = Number(value);
        if (!Number.isFinite(n)) return fallback;
        return Math.min(max, Math.max(min, n));
    }

    function loadSettings() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (!raw) return { ...defaultSettings };
            const parsed = JSON.parse(raw);
            const settings = { ...defaultSettings, ...parsed };
            if (settings.searchApiUrl === 'http://localhost:18080/search?q={keyword}&format=json&language=zh-CN') {
                settings.searchApiUrl = 'http://localhost:18080/search?q={keyword}&format=json&language={language}';
            }
            return settings;
        } catch (e) {
            warn('设置读取失败，使用默认设置', e);
            return { ...defaultSettings };
        }
    }

    function saveSettings(settings) {
        const normalized = { ...defaultSettings, ...settings };
        localStorage.setItem(STORAGE_KEY, JSON.stringify(normalized));
        return normalized;
    }

    function getDocumentCandidates() {
        const docs = [];
        try { if (window.document) docs.push(window.document); } catch {}
        try { if (window.parent?.document && !docs.includes(window.parent.document)) docs.push(window.parent.document); } catch {}
        try { if (window.top?.document && !docs.includes(window.top.document)) docs.push(window.top.document); } catch {}
        return docs;
    }

    function findTargetDocument() {
        for (const doc of getDocumentCandidates()) {
            try {
                if (doc.getElementById(CONTAINER_ID)) return doc;
                if (doc.getElementById('extensions_settings2')) return doc;
            } catch {}
        }
        return document;
    }

    function ensureContainer(doc) {
        let container = doc.getElementById(CONTAINER_ID);
        if (container) return container;
        const settingsRoot = doc.getElementById('extensions_settings2');
        if (!settingsRoot) return null;
        container = doc.createElement('div');
        container.id = CONTAINER_ID;
        container.className = 'extension_container';
        settingsRoot.appendChild(container);
        return container;
    }

    function getSTWindow() {
        const candidates = [];
        try { candidates.push(window); } catch {}
        try { candidates.push(window.parent); } catch {}
        try { candidates.push(window.top); } catch {}
        for (const win of candidates) {
            try {
                if (!win) continue;
                if (win.SillyTavern) return win;
                if (typeof win.generate === 'function') return win;
            } catch {}
        }
        return window;
    }

    function ST() { return getSTWindow().SillyTavern || window.SillyTavern; }

    function getFn(name) { return getSTWindow()?.[name] || window?.[name]; }

    function normalizeBaseURL(url) {
        const value = String(url || '').trim().replace(/\/+$/, '');
        if (!value) return '';
        if (value.endsWith('/v1')) return value;
        if (value.endsWith('/models')) return value.replace(/\/models$/, '');
        if (value.endsWith('/chat/completions')) return value.replace(/\/chat\/completions$/, '');
        return `${value}/v1`;
    }

    function getCustomApiConfig(settings = loadSettings()) {
        if (settings.analysisApi !== 'custom') return undefined;
        return {
            apiurl: normalizeBaseURL(settings.customApiUrl),
            key: settings.customApiKey || '',
            model: settings.customModel || '',
            source: 'openai',
            max_tokens: Math.max(0, Number(settings.customMaxTokens || 0)),
            temperature: clampNumber(settings.customTemperature, 0, 2, 1),
            frequency_penalty: clampNumber(settings.customFrequencyPenalty, -2, 2, 0),
            presence_penalty: clampNumber(settings.customPresencePenalty, -2, 2, 0),
            top_p: clampNumber(settings.customTopP, 0, 1, 1),
            top_k: clampNumber(settings.customTopK, 0, 500, 0),
        };
    }

    function getPresetNames() {
        try {
            const fn = getFn('getPresetNames');
            if (typeof fn !== 'function') return [];
            return fn().map(x => String(x || '').trim()).filter(Boolean).filter(x => x !== 'in_use').sort((a, b) => a.localeCompare(b, 'zh-Hans-CN'));
        } catch (e) { return []; }
    }

    function getPresetObject(name) {
        const fn = getFn('getPreset');
        if (typeof fn !== 'function') throw new Error('无 getPreset 接口');
        return fn(name);
    }

    async function fetchModelsFromCustomApi(settings = loadSettings()) {
        if (runtimeModelLoading) return runtimeModelList;
        const apiurl = normalizeBaseURL(settings.customApiUrl);
        if (!apiurl) { toast('请先填写 API 地址', 'warning'); return []; }
        runtimeModelLoading = true;
        updateModelButtonLoading(true);
        try {
            const getModelList = getFn('getModelList');
            if (typeof getModelList === 'function') {
                runtimeModelList = await getModelList({ apiurl, key: settings.customApiKey || '' });
            } else {
                const headers = ST()?.getRequestHeaders?.() || {};
                const resp = await fetch('/api/backends/chat-completions/status', {
                    method: 'POST', headers,
                    body: JSON.stringify({ reverse_proxy: apiurl, proxy_password: settings.customApiKey || '', chat_completion_source: 'openai' }),
                });
                const json = await resp.json();
                runtimeModelList = (json?.data || []).map(x => String(x?.id ?? '').trim()).filter(Boolean);
            }
            runtimeModelList = [...new Set(runtimeModelList)].sort();
            const doc = findTargetDocument();
            const s = doc.getElementById('search_custom_model_select');
            if (s) { s.innerHTML = getModelOptionsHtml(doc.getElementById('search_custom_model')?.value || settings.customModel); s.disabled = !runtimeModelList.length; }
            toast(runtimeModelList.length ? `已获取 ${runtimeModelList.length} 个模型` : '模型列表为空', runtimeModelList.length ? 'success' : 'warning');
            return runtimeModelList;
        } catch (e) { toast(`获取失败：${e.message}`, 'error'); return []; }
        finally { runtimeModelLoading = false; updateModelButtonLoading(false); }
    }

    function updateModelButtonLoading(loading) {
        const btn = findTargetDocument().getElementById('search_fetch_models_btn');
        if (!btn) return;
        btn.value = loading ? '获取中…' : '获取模型';
        btn.disabled = !!loading;
    }

    function getModelOptionsHtml(selected) {
        if (!runtimeModelList.length) return `<option value="">暂无模型列表</option>`;
        return [`<option value="">（从列表选择）</option>`, ...runtimeModelList.map(m => `<option value="${escapeHtml(m)}" ${m===selected?'selected':''}>${escapeHtml(m)}</option>`)].join('');
    }

    function getPresetOptionsHtml(selected) {
        const presets = getPresetNames();
        if (!presets.length) return `<option value="">无可用预设</option>`;
        return presets.map(n => `<option value="${escapeHtml(n)}" ${n===selected?'selected':''}>${escapeHtml(n)}</option>`).join('');
    }

    async function searchCustomApi(keyword, signal) {
        const settings = loadSettings();
        const url = settings.searchApiUrl?.trim();
        if (!url) return null;

        const method = (settings.searchApiMethod || 'GET').toUpperCase();
        const key = settings.searchApiKey?.trim() || '';
        const language = settings.searchApiLanguage?.trim() || 'zh-CN';
        const shouldUseLanguage = language && language !== 'auto';

        const headers = { 'Accept': 'application/json' };
        if (key && settings.searchApiKeyHeaderName?.trim()) {
            const template = settings.searchApiKeyHeaderTemplate?.trim() || '{key}';
            headers[settings.searchApiKeyHeaderName.trim()] = template.replaceAll('{key}', key);
        }

        try {
            let finalUrl = url
                .replaceAll('{keyword}', encodeURIComponent(keyword))
                .replaceAll('{language}', encodeURIComponent(language));
            let body = null;

            if (method === 'POST') {
                if (!headers['Content-Type']) headers['Content-Type'] = 'application/json';
                const template = settings.searchApiBodyTemplate?.trim() || '{"query":"{keyword}"}';
                body = template
                    .replaceAll('{keyword}', escapeJsonStringContent(keyword))
                    .replaceAll('{language}', escapeJsonStringContent(language));
            } else {
                if (key && settings.searchApiQueryParam?.trim()) {
                    finalUrl = appendQueryParam(finalUrl, settings.searchApiQueryParam.trim(), key);
                }
                if (settings.searchApiExtraParams?.trim()) {
                    const extra = settings.searchApiExtraParams.trim()
                        .replaceAll('{keyword}', encodeURIComponent(keyword))
                        .replaceAll('{language}', encodeURIComponent(language));
                    finalUrl += (extra.startsWith('&') || extra.startsWith('?') ? '' : (finalUrl.includes('?') ? '&' : '?')) + extra;
                }
                if (shouldUseLanguage && !hasQueryParam(finalUrl, 'language') && !hasQueryParam(finalUrl, 'lang')) {
                    finalUrl = appendQueryParam(finalUrl, 'language', language);
                }
            }

            log(`自定义搜索: ${method} ${finalUrl}`);
            const fetchOpts = { method, headers, signal };
            if (body) fetchOpts.body = body;

            const resp = await fetch(finalUrl, fetchOpts);
            if (!resp.ok) { warn(`自定义搜索 HTTP ${resp.status}`); return null; }

            const data = await resp.json();
            return extractSearchResults(data, keyword, settings);
        } catch (e) {
            if (e.name !== 'AbortError') warn(`自定义搜索失败: ${keyword}`, e.message);
            return null;
        }
    }

    function extractSearchResults(data, keyword, settings) {
        const path = settings.searchApiResultPath?.trim() || 'results';
        let list = getByPath(data, path);
        if (!Array.isArray(list)) {
            const alternatives = ['results', 'items', 'data', 'response.results', 'organic', 'webPages.value'];
            for (const alt of alternatives) {
                list = getByPath(data, alt);
                if (Array.isArray(list)) break;
            }
        }
        if (!Array.isArray(list) || !list.length) {
            warn('搜索结果列表为空，路径:', path);
            return null;
        }

        const titleField = settings.searchApiTitleField?.trim() || 'title';
        const snippetField = settings.searchApiSnippetField?.trim() || 'content';
        const linkField = settings.searchApiLinkField?.trim() || 'url';
        const limit = settings.searchResultsCount || CONFIG.searchResultsCount;
        const maxLen = settings.maxExtractLength || CONFIG.maxExtractLength;

        const results = [];
        for (let i = 0; i < Math.min(list.length, limit * 2); i++) {
            const item = list[i];
            const title = getByPath(item, titleField) || '';
            const snippet = getByPath(item, snippetField) || '';
            const link = getByPath(item, linkField) || '';

            if (!snippet && !title) continue;

            let text = '';
            if (title) text += `【${title}】`;
            if (snippet) {
                const clean = String(snippet).replace(/<[^>]+>/g, '').replace(/\n+/g, ' ').replace(/\s+/g, ' ').slice(0, maxLen).trim();
                text += clean;
            }
            if (link) text += `\n🔗 ${link}`;

            if (text && isRelevant(keyword, text)) {
                results.push(text);
                if (results.length >= limit) break;
            }
        }

        return results.length ? results.join('\n') : null;
    }

    function getByPath(obj, path) {
        if (!obj || !path) return obj;
        const keys = path.split('.');
        let current = obj;
        for (const key of keys) {
            if (current == null) return undefined;
            if (/^\d+$/.test(key)) {
                current = current[parseInt(key)];
            } else {
                current = current[key];
            }
        }
        return current;
    }

    function isRelevant(keyword, text) {
        const kwLower = keyword.toLowerCase();
        const textLower = text.toLowerCase();
        if (textLower.includes(kwLower)) return true;
        const kwChars = [...keyword].filter(c => c.trim() && !/[a-zA-Z0-9]/.test(c));
        if (kwChars.length >= 2) return kwChars.filter(c => text.includes(c)).length >= kwChars.length * 0.5;
        const kwWords = kwLower.split(/\s+/).filter(w => w.length > 1);
        if (kwWords.length >= 2) return kwWords.filter(w => textLower.includes(w)).length >= kwWords.length * 0.5;
        return false;
    }

    async function searchWikipedia(keyword, signal) {
        try {
            const settings = loadSettings();
            const limit = settings.searchResultsCount || CONFIG.searchResultsCount;
            const maxLen = settings.maxExtractLength || CONFIG.maxExtractLength;
            let searchTerm = keyword;
            try {
                const suggestUrl = `https://zh.wikipedia.org/w/api.php?action=opensearch&search=${encodeURIComponent(keyword)}&limit=1&format=json&origin=*`;
                const suggestResp = await fetch(suggestUrl, { signal });
                if (suggestResp.ok) {
                    const suggestData = await suggestResp.json();
                    if (Array.isArray(suggestData[1]) && suggestData[1].length > 0 && suggestData[1][0] !== keyword) {
                        searchTerm = suggestData[1][0];
                    }
                }
            } catch {}
            const searchUrl = `https://zh.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(searchTerm)}&format=json&origin=*&srlimit=${limit}`;
            const searchResp = await fetch(searchUrl, { signal });
            if (!searchResp.ok) return null;
            const searchData = await searchResp.json();
            const pages = searchData?.query?.search;
            if (!pages?.length) return null;
            const pageIds = pages.map(p => p.pageid);
            const extractsUrl = `https://zh.wikipedia.org/w/api.php?action=query&prop=extracts&exintro&explaintext&pageids=${pageIds.join('|')}&format=json&origin=*`;
            const extractResp = await fetch(extractsUrl, { signal });
            if (!extractResp.ok) return null;
            const extractData = await extractResp.json();
            const extracts = [];
            for (const pid of pageIds) {
                const page = extractData?.query?.pages?.[pid];
                if (page?.extract) {
                    const clean = page.extract.replace(/\n+/g, ' ').replace(/\s+/g, ' ').slice(0, maxLen).trim();
                    if (clean && isRelevant(keyword, page.title + ' ' + clean)) extracts.push(`【${page.title}】${clean}`);
                }
            }
            return extracts.length > 0 ? extracts.join('\n') : null;
        } catch (e) {
            if (e.name !== 'AbortError') warn(`Wiki 失败: ${keyword}`, e.message);
            return null;
        }
    }

    async function searchMoegirl(keyword, signal) {
        try {
            const settings = loadSettings();
            const limit = settings.searchResultsCount || CONFIG.searchResultsCount;
            const maxLen = settings.maxExtractLength || CONFIG.maxExtractLength;
            const url = `https://zh.moegirl.org.cn/api.php?action=query&list=search&srsearch=${encodeURIComponent(keyword)}&format=json&origin=*&srlimit=${limit}`;
            const resp = await fetch(url, { signal });
            if (!resp.ok) return null;
            const data = await resp.json();
            const pages = data?.query?.search;
            if (!pages?.length) return null;
            const results = pages
                .filter(p => isRelevant(keyword, `${p.title} ${p.snippet || ''}`))
                .map(p => {
                    const snippet = String(p.snippet || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').slice(0, maxLen).trim();
                    return `【萌娘百科：${p.title}】${snippet}`;
                }).filter(Boolean);
            return results.length ? results.join('\n') : null;
        } catch (e) {
            if (e.name !== 'AbortError') warn(`萌百失败: ${keyword}`, e.message);
            return null;
        }
    }

    async function searchAllKeywords(keywords) {
        const settings = loadSettings();
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), settings.searchTimeout || CONFIG.searchTimeout);
        try {
            const tasks = [];
            for (const kw of keywords) {
                if (settings.enableWikipedia) tasks.push({ kw, source: 'wiki', promise: searchWikipedia(kw, controller.signal) });
                if (settings.enableMoegirl) tasks.push({ kw, source: 'moegirl', promise: searchMoegirl(kw, controller.signal) });
                if (settings.enableCustomSearch) tasks.push({ kw, source: 'custom', promise: searchCustomApi(kw, controller.signal) });
            }
            const results = await Promise.allSettled(tasks.map(t => t.promise));
            const searchResults = new Map();
            for (let i = 0; i < tasks.length; i++) {
                const res = results[i];
                if (res.status === 'fulfilled' && res.value) {
                    const old = searchResults.get(tasks[i].kw) || '';
                    searchResults.set(tasks[i].kw, old ? `${old}\n${res.value}` : res.value);
                }
            }
            return searchResults;
        } finally { clearTimeout(timeoutId); }
    }

    function getFullContext(currentMessageId) {
        const parts = [];
        try {
            const context = ST()?.getContext?.();
            const character = context?.characters?.[context?.characterId];
            if (character) {
                parts.push(`【角色名】${character.name || '(未知)'}`);
                if (character.description?.trim()) parts.push(`【角色描述】${character.description}`);
                if (character.personality?.trim()) parts.push(`【性格】${character.personality}`);
                if (character.scenario?.trim()) parts.push(`【场景】${character.scenario}`);
            }
            const persona = context?.personas?.[context?.personaId];
            if (persona?.description?.trim()) parts.push(`【用户人设】${persona.description}`);
        } catch (e) {}
        try {
            const getLastMessageId = getFn('getLastMessageId');
            const getChatMessages = getFn('getChatMessages');
            if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
                const lastId = currentMessageId ?? getLastMessageId();
                const startId = Math.max(0, lastId - 15);
                const messages = getChatMessages(`${startId}-${lastId}`);
                parts.push(`【聊天记录】\n${messages.filter(m => !m.is_hidden).map(m => {
                    const who = m.role === 'user' ? '用户' : (m.name || m.role);
                    return `[${who}] ${(m.message || '').slice(0, 300)}`;
                }).join('\n')}`);
            }
        } catch (e) {}
        return parts.join('\n\n');
    }

    async function callCustomAnalysisApi({ system, user }, settings) {
        const apiurl = normalizeBaseURL(settings.customApiUrl);
        const model = String(settings.customModel || '').trim();

        if (!apiurl) throw new Error('自定义分析 API 地址为空');
        if (!model) throw new Error('自定义分析模型为空，请选择模型后保存设置');

        const headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
        };

        if (settings.customApiKey) {
            headers.Authorization = `Bearer ${settings.customApiKey}`;
        }

        const body = {
            model,
            messages: [
                { role: 'system', content: system },
                { role: 'user', content: user },
            ],
            stream: false,
            max_tokens: Math.max(1, Number(settings.customMaxTokens || 4096)),
            temperature: clampNumber(settings.customTemperature, 0, 2, 1),
            frequency_penalty: clampNumber(settings.customFrequencyPenalty, -2, 2, 0),
            presence_penalty: clampNumber(settings.customPresencePenalty, -2, 2, 0),
            top_p: clampNumber(settings.customTopP, 0, 1, 1),
        };

        if (Number(settings.customTopK) > 0) {
            body.top_k = clampNumber(settings.customTopK, 0, 500, 0);
        }

        const resp = await fetch(`${apiurl}/chat/completions`, {
            method: 'POST',
            headers,
            body: JSON.stringify(body),
        });

        const text = await resp.text();

        if (!resp.ok) {
            throw new Error(`自定义分析 API 请求失败：HTTP ${resp.status} ${text.slice(0, 300)}`);
        }

        let json;
        try {
            json = JSON.parse(text);
        } catch {
            throw new Error(`自定义分析 API 返回非 JSON：${text.slice(0, 300)}`);
        }

        const content = json?.choices?.[0]?.message?.content
            || json?.choices?.[0]?.text
            || json?.content
            || '';

        if (!content) {
            throw new Error('自定义分析 API 返回内容为空');
        }

        return content;
    }

    async function husouGenerateTask({ system, user }) {
        const settings = loadSettings();

        if (settings.analysisApi === 'custom') {
            return await callCustomAnalysisApi({ system, user }, settings);
        }

        const win = getSTWindow();
        const generate = win.generate || window.generate;
        const generateRaw = win.generateRaw || window.generateRaw;

        const common = {
            user_input: user,
            should_silence: true,
            should_stream: false,
            max_chat_history: 0,
        };

        if (settings.searchPresetMode === 'builtin' || settings.searchPresetMode === 'current') {
            if (typeof generateRaw !== 'function') throw new Error('无 generateRaw');
            const result = await generateRaw({
                ...common,
                ordered_prompts: [
                    { role: 'system', content: system },
                    'user_input',
                ],
            });
            return typeof result === 'string' ? result : result?.content || '';
        }

        if (settings.searchPresetMode === 'other' && settings.searchPresetName) {
            if (typeof generate !== 'function') throw new Error('无 generate');
            const result = await generate({
                ...common,
                preset_name: settings.searchPresetName,
                overrides: {
                    char_description: '',
                    char_personality: '',
                    scenario: '',
                    world_info_before: '',
                    world_info_after: '',
                    persona_description: '',
                    dialogue_examples: '',
                    chat_history: { prompts: [] },
                },
                injects: [
                    {
                        role: 'system',
                        content: system,
                        position: 'in_chat',
                        depth: 0,
                        should_scan: false,
                    },
                ],
            });
            return typeof result === 'string' ? result : result?.content || '';
        }

        throw new Error('未知搜索预设模式');
    }

    async function analyzeContext(contextText) {
        if (!contextText || contextText.length < 20) return [];
        const settings = loadSettings();
        const maxKw = settings.maxKeywords || CONFIG.maxKeywords;

        let existingInjection = '';
        if (settings.smartSkip) {
            try {
                existingInjection = getCurrentInjectionFromChar();
                if (existingInjection.length > 3000) existingInjection = existingInjection.slice(0, 3000) + '...(已截断)';
            } catch (e) {}
        }

        const system = `你是专有名词提取助手。请仔细阅读以下上下文，理解当前对话中涉及的角色、作品、世界观。上下文：${contextText}`;
        const user = `以下是你之前已经搜索并注入过的内容：\n${settings.smartSkip ? (existingInjection || '（暂无已搜索内容）') : '（智能跳过已关闭，请不要因为已有搜索内容而跳过关键词）'}\n\n请根据上下文${settings.smartSkip ? '和已有搜索内容' : ''}，提取还需要搜索的专有名词。\n\n规则：\n1. 尽可能多的提取与当前角色、世界观相关的专有名词（作品名、角色名、地名、组织名、技能名、专有设定等），宁可多抓不可漏抓\n2. ${settings.smartSkip ? '只有当已有搜索内容已经将该名词的所有设定（身份、外貌、背景、人际关系、技能、剧情）全部详细覆盖、没有任何遗漏时，才跳过该名词' : '智能跳过已关闭，不要根据已注入内容跳过名词'}\n3. 只要某个名词在已有搜索内容中信息不完整、或根本没有，就必须提取\n4. 上下文已经明确提供完整信息的名词可以跳过，但如果只是一笔带过，仍然要提取\n5. 忽略日常词汇\n6. 最多 ${maxKw} 个\n\n返回纯 JSON 数组，示例：["关键词1","关键词2"]。没有就返回 []。`;
        try {
            const text = await husouGenerateTask({ system, user });
            const match = text.match(/\[[\s\S]*?\]/);
            if (!match) return [];
            const arr = JSON.parse(match[0]);
            const keywords = Array.isArray(arr) ? arr.filter(k => typeof k === 'string' && k.trim()).map(k => k.trim()).slice(0, maxKw) : [];
            updateKeywordPanel(keywords);
            return keywords;
        } catch (e) { return []; }
    }

    async function fetchPageWithJina(url, signal) {
        try {
            const settings = loadSettings();
            const maxLen = settings.maxExtractLength || CONFIG.maxExtractLength;
            const jinaUrl = `https://r.jina.ai/${url}`;
            const resp = await fetch(jinaUrl, { signal, headers: { 'Accept': 'text/plain' } });
            if (!resp.ok) return null;
            const text = await resp.text();
            return text.slice(0, maxLen).trim();
        } catch (e) {
            if (e.name !== 'AbortError') warn('Jina 抓取失败:', url, e.message);
            return null;
        }
    }

    async function filterSearchResults(searchResults) {
        const settings = loadSettings();
        if (!searchResults.size) return new Map();
        let enrichedResults = new Map(searchResults);
        if (settings.enableJinaFetch && settings.aiFilter) {
            const jinaController = new AbortController();
            const jinaTimeout = setTimeout(() => jinaController.abort(), settings.searchTimeout || CONFIG.searchTimeout);
            try {
                for (const [kw, text] of searchResults) {
                    const urls = [...text.matchAll(/🔗 (https?:\/\/\S+)/g)].map(m => m[1]).slice(0, 2);
                    const fetchedTexts = [];
                    for (const url of urls) {
                        const content = await fetchPageWithJina(url, jinaController.signal);
                        if (content) {
                            const clean = content.replace(/\n{3,}/g, '\n\n').trim();
                            fetchedTexts.push(`--- 来自 ${url} ---\n${clean}`);
                        }
                    }
                    if (fetchedTexts.length) {
                        enrichedResults.set(kw, text + '\n\n【网页全文】\n' + fetchedTexts.join('\n\n'));
                    }
                }
            } catch (e) {
                warn('Jina 抓取阶段出错:', e.message);
            } finally {
                clearTimeout(jinaTimeout);
            }
        }
        if (!settings.aiFilter) {
            return searchResults;
        }
        let contextInfo = '';
        try {
            const ctx = ST()?.getContext?.();
            const char = ctx?.characters?.[ctx?.characterId];
            if (char?.name?.trim()) {
                contextInfo += `【当前角色名】${char.name}\n`;
            }
            if (char?.description?.trim()) {
                contextInfo += `【角色设定】${char.description}\n`;
            }
            if (char?.personality?.trim()) {
                contextInfo += `【角色性格/已注入信息】${char.personality.slice(0, 8000)}\n`;
            }
            if (char?.scenario?.trim()) {
                contextInfo += `【场景】${char.scenario}\n`;
            }
        } catch (e) {}
        try {
            const getChatMessages = getFn('getChatMessages');
            const getLastMessageId = getFn('getLastMessageId');
            if (typeof getChatMessages === 'function') {
                const lastId = typeof getLastMessageId === 'function' ? Number(getLastMessageId()) : 0;
                const startId = Number.isFinite(lastId) ? Math.max(0, lastId - 299) : 0;
                const messages = Number.isFinite(lastId) && lastId > 0 ? getChatMessages(`${startId}-${lastId}`) : getChatMessages(0);
                contextInfo += `【对话记录】\n${messages.filter(m => !m.is_hidden).map(m => {
                    const who = m.role === 'user' ? '用户' : (m.name || m.role);
                    return `[${who}] ${m.message}`;
                }).join('\n')}`;
            }
        } catch (e) {}
        let raw = '';
        for (const [k, v] of enrichedResults) {
            raw += `\n=== 「${k}」===\n${v}\n`;
        }
        const system = `你是信息过滤与整理助手。
你必须先阅读当前上下文，判断搜索结果是否真的属于当前角色、当前作品、当前世界观或当前对话正在讨论的设定。
【当前上下文】
${contextInfo || '（无上下文）'}
【原始搜索结果】
${raw}
严格规则：
1. 与当前角色、作品、世界观、设定无关的人物、现实人物、新闻、百科条目、同名无关对象，必须全部丢弃。
2. 只保留能明确支持当前对话设定的信息。
3. 如果搜索结果只是同名，但无法确认属于当前角色或世界观，视为无关。
4. 如果全部无关，必须严格输出指定的“无可用信息”格式。
5. 不要解释你的判断过程，不要输出英文说明，不要说“I will discard”。
6. 不要把原始搜索结果照抄进输出。
7. 有用信息需要合并去重，并用自己的话总结。
8. 角色信息和世界观信息必须区分清楚，不要混杂。
9. 每条说明不超过4000字。`;
        const user = `请过滤并整理搜索结果。
只允许输出以下两种格式之一：
如果有相关信息，输出：
【过滤后的知识库】
【关于「名称」的说明】
核心信息...
如果全部无关或无可用信息，必须严格输出：
【过滤后的知识库】
（无可用信息）
不要解释，不要输出英文说明，不要输出判断过程。`;
        try {
            const text = await husouGenerateTask({ system, user });
            const normalized = String(text || '').trim();
            const saysNoUsefulInfo =
                /无可用信息|无相关信息|没有可用信息|没有相关信息|全部无关|完全无关|不相关|无关|丢弃|舍弃|discard|irrelevant|not relevant|no usable|no relevant/i.test(normalized);
            const match = normalized.match(/【过滤后的知识库】([\s\S]*?)(?:$|---)/);
            if (!match) {
                warn('AI过滤结果未按格式返回，已丢弃本次搜索结果，避免注入原始噪音:', normalized.slice(0, 300));
                return new Map();
            }
            const content = match[1].trim();
            if (!content || saysNoUsefulInfo || /（?\s*无可用信息\s*）?/i.test(content)) {
                log('AI过滤判定：无可用信息，已丢弃搜索结果');
                return new Map();
            }
            const map = new Map();
            const sections = content.split(/【关于「(.+?)」的说明】/);
            for (let i = 1; i < sections.length; i += 2) {
                const name = sections[i]?.trim();
                const body = sections[i + 1]?.trim();
                if (!name || !body) continue;
                if (/无可用信息|无相关信息|没有可用信息|没有相关信息|全部无关|完全无关|不相关|无关|discard|irrelevant|no usable|no relevant/i.test(body)) continue;
                map.set(name, body);
            }
            if (!map.size) {
                warn('AI过滤结果没有可解析条目，已丢弃本次搜索结果，避免注入原始噪音:', normalized.slice(0, 300));
                return new Map();
            }
            return map;
        } catch (e) {
            warn('AI过滤失败，已丢弃本次搜索结果，避免注入原始噪音:', e.message);
            return new Map();
        }
    }

    function getCurrentInjectionFromChar() {
        try {
            const char = ST()?.getContext?.()?.characters?.[ST().getContext?.()?.characterId];
            if (!char) return '';
            const p = char.personality || '';
            const start = '【🦊狐搜外部搜索参考';
            const end = '【外部搜索参考结束】';
            const s = p.indexOf(start);
            if (s === -1) { const os = p.indexOf('【🔍 外部搜索参考'); if (os === -1) return ''; const oe = p.indexOf(end, os); return oe === -1 ? '' : p.slice(os, oe + end.length); }
            const e = p.indexOf(end, s);
            return e === -1 ? '' : p.slice(s, e + end.length);
        } catch { return ''; }
    }

    async function saveToCharPersonality(filteredResults) {
        const settings = loadSettings();
        if (!settings.saveToPersonality || !filteredResults?.size) return;
        const timestamp = new Date().toISOString().split('T')[0];
        try {
            const ctx = ST()?.getContext?.();
            const char = ctx?.characters?.[ctx?.characterId];
            if (!char) return;
            const entries = [...filteredResults].map(([n, c]) => `【关于「${n}」的说明】\n${c}`);
            const block = `\n\n【🦊狐搜外部搜索参考 - ${timestamp}】\n${entries.join('\n\n')}\n【外部搜索参考结束】`;
            let newP = char.personality || '';
            if (settings.appendMode) {
                newP = (newP ? newP + '\n' : '') + block;
            } else {
                if (newP.includes('【🦊狐搜外部搜索参考')) newP = newP.split('【🦊狐搜外部搜索参考')[0].trim() + block;
                else if (newP.includes('【🔍 外部搜索参考')) newP = newP.split('【🔍 外部搜索参考')[0].trim() + block;
                else newP = (newP ? newP + '\n' : '') + block;
            }
            char.personality = newP;
            const ee = getFn('eventEmit');
            if (ee) await ee(getSTWindow().tavern_events?.CHARACTER_EDITED, { detail: { id: ctx.characterId, character: char } });
            log('已保存到角色性格');
        } catch (e) { warn('保存失败', e); }
    }

    async function clearSearchInjection() {
        try {
            const ctx = ST()?.getContext?.();
            const char = ctx?.characters?.[ctx?.characterId];
            if (!char) { toast('无角色卡', 'error'); return; }
            let cleaned = char.personality || '';
            const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            cleaned = cleaned.replace(new RegExp(`\\n*${esc('【🦊狐搜外部搜索参考')}[\\s\\S]*?${esc('【外部搜索参考结束】')}\\n*`, 'g'), '');
            cleaned = cleaned.replace(new RegExp(`\\n*${esc('【🔍 外部搜索参考')}[\\s\\S]*?${esc('【外部搜索参考结束】')}\\n*`, 'g'), '');
            if (cleaned.trim() === (char.personality||'').trim()) { toast('🧹 无搜索注入', 'info'); return; }
            char.personality = cleaned.trim();
            const ee = getFn('eventEmit');
            if (ee) await ee(getSTWindow().tavern_events?.CHARACTER_EDITED, { detail: { id: ctx.characterId, character: char } });
            pendingInject = null;
            toast('🧹 已清除', 'success');
            refreshInjectionManager();
        } catch (e) { toast('清除失败', 'error'); }
    }

