// ══════════════ 运行时钩子 ══════════════

// 魔力转化自动推导（淫化驱动：原始力量被淫魔力替换）
//   <40 无转化；40~69 原魔力 → 污染形态（圣邪光/堕灵气/淫魔导）；≥70 → 淫魔力（完全替换）
const deriveConversion = (magic, arch) => {
  const type = _.get(magic, "类型", "无");
  const lust = Number(_.get(arch, "淫化度", 0)) || 0;
  switch (type) {
    case "圣光": return lust >= 40 ? (lust >= 70 ? "淫魔力" : "圣邪光") : "无";
    case "灵气": return lust >= 40 ? (lust >= 70 ? "淫魔力" : "堕灵气") : "无";
    case "魔导": return lust >= 40 ? (lust >= 70 ? "淫魔力" : "淫魔导") : "无";
    case "淫魔力": return "无";
    default: return "无";
  }
};

const eventIds = ["已完成事件", "事件", "事件提示"];

// 注入 prompts：已完成事件 + 事件状态
const N = list => {
  const prompts = _.map(list, ({ id: t, content: e, position: r = "none", depth: a = 0, role: s = "system" }) => ({
    id: t, content: e, position: r, depth: a, role: s, should_scan: true
  }));
  injectPrompts(prompts);
};

const injectEventPrompts = data => {
  uninjectPrompts([...eventIds]);
  const ev = _.get(data, "事件", {});
  const completed = _.get(ev, "已完成事件", []);
  const prompts = [];
  if (Array.isArray(completed) && completed.length > 0) {
    prompts.push({ id: "已完成事件", content: completed.join("; "), position: "none", depth: 0, role: "system" });
  }
  if (ev.开启 === true && ev.结束 !== true && ev.标题) {
    prompts.push({ id: "事件", content: `当前事件为${ev.标题}，当前阶段为${ev.阶段 || ''}`, position: "none", depth: 0, role: "system" });
    prompts.push({ id: "事件提示", content: "（IMPORTANT: 当前剧情事件进行中，你必须按照<event>中内容发展剧情，不得太过偏离剧情事件）", position: "in_chat", depth: 0, role: "system" });
  }
  if (prompts.length > 0) N(prompts);
};

// VARIABLE_UPDATE_ENDED 主钩子：校验 + 魔力转化 + 事件结束处理 + prompt 注入
const ct = (e, r) => {
  const raw = _.get(e, "stat_data", {});
  const parsed = g.safeParse(raw);
  if (!parsed.success) console.error("[临空市] stat_data 校验失败", parsed.error);
  const data = parsed.success ? parsed.data : raw;

  // 魔力转化自动推导
