    }

    @keyframes lineShift {
      0%, 100% { opacity: 0.3; transform: translateX(0); }
      25% { opacity: 0.6; transform: translateX(2%); }
      50% { opacity: 0.25; transform: translateX(-1%); }
      75% { opacity: 0.55; transform: translateX(1.5%); }
    }
    @keyframes orbFloat1 {
      0%, 100% { transform: translate(0, 0) scale(1); }
      33% { transform: translate(40%, 30%) scale(1.2); }
      66% { transform: translate(15%, 50%) scale(0.85); }
    }
    @keyframes orbFloat2 {
      0%, 100% { transform: translate(0, 0) scale(1); }
      40% { transform: translate(-30%, -20%) scale(1.25); }
      70% { transform: translate(-15%, -40%) scale(0.9); }
    }
    @keyframes orbFloat3 {
