    }
    @keyframes ascParticle {
      0%, 100% { transform: translateY(0) scale(1); opacity: var(--po, 0.3); }
      50% { transform: translateY(-8px) scale(1.1); opacity: calc(var(--po, 0.3) * 1.4); }
    }
    @keyframes pulseVertical {
      0%, 100% { transform: scaleY(0.4); opacity: calc(var(--po, 0.3) * 0.3); }
      50% { transform: scaleY(1); opacity: var(--po, 0.3); }
